    // Component definitions
    const ThreadTreeNode = ({ thread, threads, messages, currentView, onNavigate, getThreadMessages, level }) => {
      const [isExpanded, setIsExpanded] = useState(true);
      const childThreads = threads.filter(t => t.parentThreadId === thread.id);
      const threadMessages = getThreadMessages(thread.id);
      const isCurrentView = currentView === thread.id;

      return (
        <div className={`${level > 0 ? 'ml-4 border-l-2 border-gray-200 pl-3' : ''}`}>
          <div
            className={`p-3 rounded-lg cursor-pointer transition-all ${
              isCurrentView 
                ? 'border-blue-500 bg-blue-50 border-2' 
                : 'border-gray-200 hover:border-blue-300 hover:bg-gray-50 border'
            }`}
            onClick={() => onNavigate(thread.id)}
          >
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center space-x-2">
                <span className={`text-xs font-medium px-2 py-1 rounded ${
                  level === 0 ? 'bg-blue-100 text-blue-700' : 'bg-purple-100 text-purple-700'
                }`}>
                  #{thread.id.slice(-4)}
                </span>
                {thread.level > 1 && (
                  <span className="text-xs bg-gray-100 text-gray-600 px-2 py-1 rounded">
                    L{thread.level}
                  </span>
                )}
                {thread.isSuggested && (
                  <span className="text-xs bg-yellow-100 text-yellow-600 px-1 py-0.5 rounded">💡</span>
                )}
              </div>
              <div className="flex items-center space-x-2">
                <span className="text-xs text-gray-500">{threadMessages.length} msg</span>
                {childThreads.length > 0 && (
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      setIsExpanded(!isExpanded);
                    }}
                    className="text-xs text-gray-400 hover:text-gray-600"
                  >
                    {isExpanded ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
                  </button>
                )}
              </div>
            </div>

            <p className="text-xs text-gray-600 line-clamp-2">
              {thread.selectedText ? 
                `"${thread.selectedText.slice(0, 40)}..."` : 
                `${threadMessages.length} messages`
              }
            </p>
          </div>

          {/* Child Threads */}
          {isExpanded && childThreads.map(childThread => (
            <ThreadTreeNode
              key={childThread.id}
              thread={childThread}
              threads={threads}
              messages={messages}
              currentView={currentView}
              onNavigate={onNavigate}
              getThreadMessages={getThreadMessages}
              level={level + 1}
            />
          ))}
        </div>
      );
    };

    const MessageBubble = ({ 
      message, 
      onTextSelection, 
      selectedText, 
      selectionContext, 
      onCreateThread, 
      onCreateSelectedThread,
      siblingThreads,
      suggestedThreads,
      onCreateSuggestedThread,
      threadDropdown,
      onToggleDropdown,
      onNavigateToThread
    }) => {
      const bubbleRef = React.useRef(null);

      // Enhanced selection handler for multi-line/formatting
      const handleBubbleTextSelection = () => {
        const selection = window.getSelection();
        if (!selection || selection.rangeCount === 0) return;
        const range = selection.getRangeAt(0);
        const bubbleNode = bubbleRef.current;
        if (!bubbleNode) return;
        // Check if selection is fully within this bubble
        if (bubbleNode.contains(range.startContainer) && bubbleNode.contains(range.endContainer)) {
          const selectedText = selection.toString().trim();
          if (selectedText.length > 5) {
            onTextSelection(message.id, message.content, selectedText);
          }
        }
      };

      return (
        <div className={`flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
          <div
            ref={bubbleRef}
            className={`max-w-3xl px-4 py-3 rounded-2xl ${
              message.sender === 'user'
                ? 'bg-blue-600 text-white'
                : 'bg-white text-gray-900 border border-gray-200 shadow-sm'
            } relative group`}
            onMouseUp={() => onTextSelection(message.id, message.content)}
          >
