              </div>
            )}

            {/* Thread Preview */}
            {!isCollapsed && (
              <div className="mt-4 space-y-3">
                {threadMessages.slice(0, compactMode ? 2 : 3).map((msg) => (
                  <div
                    key={msg.id}
                    className={`p-3 rounded-lg text-sm ${
                      msg.sender === 'user'
                        ? 'bg-blue-100 text-blue-900 ml-6'
                        : 'bg-white text-gray-900 border border-gray-200 mr-6'
                    }`}
                  >
                    {msg.content}
                  </div>
                ))}

                {compactMode && threadMessages.length > 2 && (
                  <div className="text-center text-sm text-blue-600">
                    +{threadMessages.length - 2} more messages
                  </div>
                )}

                {threadMessages.length === 0 && (
                  <div className="text-center py-4 text-gray-500 text-sm">
                    💬 Click "Open" to start discussion
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Child Threads (Sub-threads) */}
          {childThreads.length > 0 && (
            <div className="mt-3 space-y-3">
              {childThreads.map(childThread => (
                <ThreadCard
                  key={childThread.id}
                  thread={childThread}
                  threads={threads}
                  messages={messages}
                  compactMode={compactMode}
                  onNavigateToThread={onNavigateToThread}
                  onOpenThread={onOpenThread}
                  onToggleThread={onToggleThread}
                  onResolveThread={onResolveThread}
                  onInviteToThread={onInviteToThread}
                  getThreadMessages={getThreadMessages}
                  getSiblingThreads={getSiblingThreads}
                  getChildThreads={getChildThreads}
                  level={level + 1}
                />
              ))}
            </div>
          )}
        </div>
      );
    };

    const ThreadView = ({ 
      threadId, 
      threads, 
      messages, 
      availableModels, 
      suggestedQuestions,
      isTyping,
      onSwitchModel,
      onOpenSubThread,
      onInviteToThread,
      getRelatedThreads,
      getThreadMessages,
      canInvite,
      selectedText,
      setSelectedText,
      selectionContext,
      setSelectionContext,
      handleTextSelection,
      activeUsers,
      openThread
    }) => {
      const currentThread = threads.find(t => t.id === threadId);
      const threadMessages = getThreadMessages(threadId);
      const related = getRelatedThreads(threadId);
      const parentMessage = currentThread && messages.find(m => m.id === currentThread.parentMsgId);

      if (!currentThread) {
        return <div className="flex-1 flex items-center justify-center text-gray-500">Thread not found</div>;
      }

      // 2. In ThreadView, add a model selector for the thread input
      const threadModel = threadInputModels[threadId] || currentThread.model || currentModel;

      // Define sendThreadMessage INSIDE ThreadView
      const sendThreadMessage = (text, threadIdParam) => {
        const model = threadInputModels[threadIdParam] || currentThread.model || currentModel;
        sendMessage(text, threadIdParam, model);
      };

      return (
        <div className="flex-1 flex flex-col">
          {/* Enhanced Thread Header */}
          <div className="bg-gradient-to-r from-blue-50 to-purple-50 border-b border-gray-200 p-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-4">
                <div className="flex items-center space-x-3">
                  <GitBranch className="w-6 h-6 text-blue-600" />
                  <div>
                    <div className="flex items-center space-x-2">
                      <h2 className="text-lg font-semibold text-gray-900">
                        Thread #{threadId.slice(-4)}
                      </h2>
                      {currentThread.level > 1 && (
                        <span className="text-sm bg-purple-100 text-purple-600 px-2 py-1 rounded">
                          Level {currentThread.level}
                        </span>
                      )}
                    </div>

                    {/* Users online under thread name */}
                    {activeUsers.length > 1 && (
                      <div className="flex items-center space-x-2 mt-1">
                        <div className="flex -space-x-1">
                          {activeUsers.slice(0, 4).map(user => (
                            <div key={user.id} className="w-5 h-5 bg-white rounded-full border border-gray-300 flex items-center justify-center text-xs">
                              {user.avatar}
                            </div>
                          ))}
                          {activeUsers.length > 4 && (
                            <div className="w-5 h-5 bg-gray-100 rounded-full border border-gray-300 flex items-center justify-center text-xs font-medium text-gray-600">
                              +{activeUsers.length - 4}
                            </div>
                          )}
                        </div>
                        <span className="text-xs text-gray-600">{activeUsers.length} online</span>
                      </div>
                    )}
                  </div>
                </div>
              </div>

              <div className="flex items-center space-x-3">
                {/* Collaborate button for this thread */}
                <button
                  onClick={() => onInviteToThread(currentThread.id)}
                  className="px-3 py-1.5 bg-green-600 text-white text-sm rounded-lg hover:bg-green-700 transition-colors font-medium"
                >
                  <Users className="w-4 h-4 mr-1" /> Collaborate
                </button>
                {/* Export Outcome button */}
                <button
                  onClick={() => {
                    setExportOutcomeModal({ open: true, threadId });
                    const threadMsgs = getThreadMessages(threadId).map(m => `${m.sender === 'user' ? 'User' : 'AI'}: ${m.content}`).join('\n');
                    setOutcomeText(threadMsgs.slice(0, 1000));
                    setOutcomeModel(threadInputModels[threadId] || currentThread.model || currentModel);
                    setOutcomeTarget('main');
                  }}
                  className="px-3 py-1.5 bg-yellow-500 text-white text-sm rounded-lg hover:bg-yellow-600 transition-colors font-medium"
                >
                  <Download className="w-4 h-4 mr-1" /> Export Outcome
                </button>
                {/* Settings Menu */}
                <div className="relative group">
                  <button 
                    className="p-2 text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                    onClick={(e) => e.preventDefault()}
                  >
                    <Settings className="w-5 h-5" />
                  </button>

                  <div className="absolute right-0 top-full mt-1 w-56 bg-white rounded-lg shadow-lg border border-gray-200 py-2 z-10 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all">
                    {/* Model Selection */}
                    <div className="px-3 py-2 border-b border-gray-100">
                      <div className="text-xs font-medium text-gray-700 mb-2">AI Model</div>
                      <select
                        value={threadModel}
                        onChange={e => setThreadInputModels(prev => ({ ...prev, [threadId]: e.target.value }))}
                        className="px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 mr-2"
                      >
                        {availableModels.map(model => (
                          <option key={model.id} value={model.id}>{model.name} ({model.type})</option>
                        ))}
                      </select>
                    </div>

                    {/* Thread Actions */}
                    <div className="px-3 py-2 border-b border-gray-100">
                      <div className="text-xs font-medium text-gray-700 mb-2">Thread Actions</div>
                      <div className="space-y-1">
                        <button
                          onClick={() => openThread(currentThread.parentMsgId, null, currentThread.id)}
                          className="w-full text-left px-2 py-1 text-sm hover:bg-gray-50 rounded flex items-center space-x-2"
                        >
                          <Plus className="w-4 h-4" />
                          <span>Create Sub-thread</span>
                        </button>

                        {canInvite && (
                          <button
                            onClick={() => onInviteToThread(currentThread.id)}
                            className="w-full text-left px-2 py-1 text-sm hover:bg-gray-50 rounded flex items-center space-x-2"
                          >
                            <Users className="w-4 h-4" />
                            <span>Collaborate</span>
                          </button>
                        )}
                      </div>
                    </div>

                    {/* Navigation Info */}
                    <div className="px-3 py-2">
                      <div className="text-xs font-medium text-gray-700 mb-2">Thread Info</div>
                      <div className="space-y-1 text-xs text-gray-600">
                        <div>Level {currentThread.level} Thread</div>
                        <div>{threadMessages.length} messages</div>
                        {related.siblings.length > 0 && (
                          <div>{related.siblings.length} sibling threads</div>
                        )}
                        {related.children.length > 0 && (
                          <div>{related.children.length} sub-threads</div>
                        )}
                        {currentThread.selectedText && (
                          <div className="flex items-center space-x-1">
                            <Target className="w-3 h-3" />
                            <span>Text-focused</span>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Show only the selected text as context if present */}
            {currentThread.contextText ? (
              <div className="mt-4 p-3 bg-white rounded-lg border-l-4 border-blue-500">
                <div className="text-xs text-gray-500 mb-1">Selected Text Focus</div>
                <p className="text-sm text-gray-800">"{currentThread.contextText}"</p>
              </div>
            ) : parentMessage && (
              <div className="mt-4 p-3 bg-white rounded-lg border-l-4 border-blue-500">
                <div className="text-xs text-gray-500 mb-1">Original Context</div>
                <p className="text-sm text-gray-800">{parentMessage.content.slice(0, 100)}...</p>
              </div>
            )}
          </div>

          {/* Thread Messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4">
            {threadMessages.map((msg, index) => (
              <div key={msg.id} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div 
                  className={`max-w-3xl px-4 py-3 rounded-2xl ${
                    msg.sender === 'user'
                      ? 'bg-blue-600 text-white'
                      : msg.isPlugin
                      ? 'bg-purple-50 text-purple-900 border border-purple-200'
                      : 'bg-white text-gray-900 border border-gray-200 shadow-sm'
                  } relative group`}
                  onMouseUp={() => {
                    if (msg.sender === 'AI') {
                      handleTextSelection(msg.id, msg.content);
                    }
                  }}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      {/* Real demonstration based on model type */}
                      {(() => {
                        const modelObj = availableModels.find(m => m.id === msg.model);
                        if (modelObj?.type === 'visual') {
                          return <div className="my-2"><img src="https://placehold.co/400x200?text=AI+Image" alt="AI Visual" className="rounded-lg border" /><div className="text-xs text-gray-500 mt-1">[Image generated by {modelObj.name}]</div></div>;
                        }
                        if (modelObj?.type === 'audio') {
                          return <div className="my-2"><audio controls src=""><track kind="captions" />Your browser does not support the audio element.</audio><div className="text-xs text-gray-500 mt-1">[Audio generated by {modelObj.name}]</div></div>;
                        }
                        if (modelObj?.type === 'video') {
                          return <div className="my-2"><video controls width="320"><source src="" type="video/mp4" />Your browser does not support the video tag.</video><div className="text-xs text-gray-500 mt-1">[Video generated by {modelObj.name}]</div></div>;
                        }
                        if (modelObj?.type === 'app') {
                          return <div className="my-2 p-4 bg-gray-100 border rounded-lg"><Code className="inline w-4 h-4 mr-1" />[App workflow generated by {modelObj.name}]</div>;
                        }
                        // Default: text
                        return <p className="text-sm leading-relaxed">{msg.content}</p>;
                      })()}

                      {/* ... rest of message meta ... */}
                    </div>
                  </div>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white border border-gray-200 px-4 py-3 rounded-2xl shadow-sm">
                  <div className="flex space-x-2">
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0.1s'}}></div>
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></div>
                  </div>
                </div>
              </div>
            )}

            {/* AI Suggestions for Thread Continuation */}
            {suggestedQuestions.length > 0 && (
              <div className="bg-yellow-50 rounded-lg p-4 border border-yellow-200">
                <h4 className="text-sm font-medium text-yellow-800 mb-3 flex items-center">
                  <Zap className="w-4 h-4 mr-2" />
                  Continue the discussion
                </h4>
                <div className="space-y-2">
                  {suggestedQuestions.map((question, index) => (
                    <button
                      key={index}
                      onClick={() => sendThreadMessage(question, currentThread.id, threadModel)}
                      className="w-full text-left text-sm p-3 bg-white border border-yellow-300 rounded-lg hover:bg-yellow-100 transition-colors"
                    >
                      {question}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Thread Input */}
          <div className="p-4 border-t border-gray-200 bg-white">
            <div className="flex space-x-3">
              <input
                type="text"
                placeholder={`Continue ${currentThread.contextText ? 'focused' : 'thread'} discussion...`}
                className="flex-1 px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                onKeyPress={(e) => {
                  if (e.key === 'Enter' && e.target.value.trim()) {
                    sendThreadMessage(e.target.value, currentThread.id);
                    e.target.value = '';
                  }
                }}
              />
              <button
                onClick={e => {
                  const input = e.target.parentElement.querySelector('input');
                  if (input?.value.trim()) {
                    sendThreadMessage(input.value, currentThread.id);
                    input.value = '';
                  }
                }}
                className="px-4 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
              >
                <Send className="w-5 h-5" />
              </button>
            </div>

            {/* Thread-specific status */}
            <div className="flex items-center justify-between mt-3 text-xs text-gray-500">
              <div className="flex items-center space-x-3">
                <span>Level {currentThread.level} Thread</span>
                <span>{threadMessages.length} messages</span>
                {currentThread.selectedText && (
                  <span className="flex items-center space-x-1">
                    <Target className="w-3 h-3" />
                    <span>Text-focused</span>
                  </span>
                )}
              </div>
              <div className="flex items-center space-x-2">
                <span className="w-2 h-2 bg-green-400 rounded-full"></span>
                <span>{threadModel}</span>
              </div>
            </div>
          </div>
        </div>
      );
    };

    // 2. Add hasMainMessages at the top of the component
    const hasMainMessages = messages.filter(m => m.sessionId === currentSessionId && !m.threadId).length > 0;

    return (
      <div className="h-screen flex flex-col bg-gray-50">
        <OnboardingTour />
        <CollaborationModal />

        {/* Enhanced Header */}
        <header className="bg-white border-b border-gray-200 px-4 py-3 flex items-center justify-between shadow-sm">
          <div className="flex items-center space-x-4" id="navigation">
            <button
              onClick={() => setSidebarOpen(!sidebarOpen)}
              className="p-2 hover:bg-gray-100 rounded-lg transition-colors lg:hidden"
            >
              <Menu className="w-5 h-5" />
            </button>

            {currentView !== 'main' && (
              <button
                onClick={navigateBack}
                className="flex items-center space-x-2 px-3 py-2 text-sm text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors"
              >
                <ArrowLeft className="w-4 h-4" />
                <span>Back</span>
              </button>
            )}

            {/* Enhanced Breadcrumbs */}
            <nav className="flex items-center space-x-2 text-sm">
              {breadcrumbs.map((crumb, index) => (
                <React.Fragment key={crumb.id}>
                  <button
                    onClick={() => jumpTo(crumb.id)}
                    className={`font-medium transition-colors ${
                      index === breadcrumbs.length - 1 
                        ? 'text-gray-900' 
                        : 'text-blue-600 hover:text-blue-800'
                    }`}
                  >
                    {crumb.label}
                  </button>
                  {index < breadcrumbs.length - 1 && (
                    <ChevronRight className="w-4 h-4 text-gray-400" />
                  )}
                </React.Fragment>
              ))}
            </nav>
          </div>

          <div className="flex items-center space-x-3">
            {/* Settings Menu */}
            <div className="relative group">
              <button 
                className="p-2 text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                onClick={(e) => e.preventDefault()}
              >
                <Settings className="w-5 h-5" />
              </button>

              <div className="absolute right-0 top-full mt-1 w-56 bg-white rounded-lg shadow-lg border border-gray-200 py-2 z-10 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all">
                {/* Collaboration */}
                {canInvite && (
                  <button
                    onClick={() => {
                      setCurrentInviteThread(null);
                      setInviteModal(true);
                    }}
                    className="w-full text-left px-3 py-2 text-sm hover:bg-gray-50 flex items-center space-x-2"
                  >
                    <Users className="w-4 h-4" />
                    <span>Collaborate</span>
                  </button>
                )}

                {/* Compact Mode */}
                <button
                  onClick={() => setCompactMode(!compactMode)}
                  className="w-full text-left px-3 py-2 text-sm hover:bg-gray-50 flex items-center space-x-2"
                >
                  {compactMode ? <Maximize2 className="w-4 h-4" /> : <Minimize2 className="w-4 h-4" />}
                  <span>{compactMode ? 'Expand View' : 'Compact View'}</span>
                </button>

                {/* Export */}
                <button
                  onClick={() => {
                    exportSession();
                    console.log('Export clicked');
                  }}
                  className="w-full text-left px-3 py-2 text-sm hover:bg-gray-50 flex items-center space-x-2"
                >
                  <Download className="w-4 h-4" />
                  <span>Export Session</span>
                </button>

                {/* Tutorial */}
                <button
                  onClick={() => {
                    setShowOnboarding(true);
                    setOnboardingStep(0);
                  }}
                  className="w-full text-left px-3 py-2 text-sm hover:bg-gray-50 flex items-center space-x-2"
                >
                  <HelpCircle className="w-4 h-4" />
                  <span>Show Tutorial</span>
                </button>

                <div className="border-t border-gray-100 my-2"></div>

                {/* New Chat */}
                <button
                  onClick={() => {
                    // Reset to clean state
                    setMessages([{
                      id: generateId(),
                      sessionId: currentSessionId,
                      content: 'Hello! How can I help you today?',
                      sender: 'AI',
                      model: 'GPT-4',
                      timestamp: new Date(),
                      threadId: null
                    }]);
                    setThreads([]);
                    setCurrentView('main');
                    setNavigationHistory(['main']);
                    setBreadcrumbs([{ label: 'Main Chat', id: 'main' }]);
                    setSuggestedQuestions([]);
                    console.log('New chat started');
                  }}
                  className="w-full text-left px-3 py-2 text-sm hover:bg-gray-50 flex items-center space-x-2"
                >
                  <Plus className="w-4 h-4" />
                  <span>New Chat</span>
                </button>
              </div>
            </div>

            {/* Users online indicator */}
            {activeUsers.length > 1 && (
              <div className="flex items-center space-x-2 px-3 py-2 bg-green-50 rounded-lg">
                <div className="flex -space-x-2">
                  {activeUsers.slice(0, 3).map(user => (
                    <div key={user.id} className="w-6 h-6 bg-white rounded-full border-2 border-white flex items-center justify-center text-xs">
                      {user.avatar}
                    </div>
                  ))}
                </div>
                <span className="text-sm text-green-800 font-medium">{activeUsers.length} online</span>
              </div>
            )}
          </div>
        </header>

        <div className="flex-1 flex overflow-hidden">
          {/* Sidebar/Thread Hierarchy */}
          {hasMainMessages && (
            <aside className={`${sidebarOpen ? 'w-80' : 'w-0'} lg:w-80 bg-white border-r border-gray-200 flex flex-col transition-all duration-300 overflow-hidden`}>
              <div className="p-4 border-b border-gray-200">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="font-semibold text-gray-900">Thread Hierarchy</h2>
                  <button
                    onClick={() => setSidebarOpen(false)}
                    className="p-1 hover:bg-gray-100 rounded lg:hidden"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>

                <div className="grid grid-cols-3 gap-2 text-sm">
                  <div className="bg-blue-50 rounded-lg p-2 text-center">
                    <div className="font-medium text-blue-900">{activeThreads.length}</div>
                    <div className="text-blue-600 text-xs">Total</div>
                  </div>
                  <div className="bg-green-50 rounded-lg p-2 text-center">
                    <div className="font-medium text-green-900">{activeThreads.filter(t => !t.parentThreadId).length}</div>
                    <div className="text-green-600 text-xs">Main</div>
                  </div>
                  <div className="bg-purple-50 rounded-lg p-2 text-center">
                    <div className="font-medium text-purple-900">{activeThreads.filter(t => t.parentThreadId).length}</div>
                    <div className="text-purple-600 text-xs">Sub</div>
                  </div>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto p-4">
                {activeThreads.length === 0 ? (
                  <div className="text-center py-8">
                    <TreePine className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                    <p className="text-gray-500 text-sm mb-2">No threads yet</p>
                    <p className="text-gray-400 text-xs">Select text or click ⚙️ to start threading</p>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {/* Show main threads with their hierarchies */}
                    {activeThreads
                      .filter(t => !t.parentThreadId)
                      .map(thread => (
                        <ThreadTreeNode 
                          key={thread.id} 
                          thread={thread} 
                          threads={threads}
                          messages={messages}
                          currentView={currentView}
                          onNavigate={navigateToThread}
                          getThreadMessages={getThreadMessages}
                          level={0}
                        />
                      ))}
                  </div>
                )}
              </div>
            </aside>
          )}
          {/* Main Content */}
          <main className="flex-1 flex flex-col">
            {!hasMainMessages && currentView === 'main' ? (
              <div className="flex-1 flex flex-col items-center justify-center min-h-screen bg-white">
                <div className="text-4xl font-semibold text-gray-900 mb-8 text-center">
                  How can I help, {currentUser?.name || 'there'}?
                </div>
                <div className="w-full max-w-2xl flex flex-col items-center">
                  <div className="flex items-center w-full bg-white border border-gray-200 rounded-2xl shadow px-6 py-5">
                    <input
                      type="text"
                      value={draftText}
                      onChange={e => setDraftText(e.target.value)}
                      onKeyPress={e => {
                        if (e.key === 'Enter' && draftText.trim()) {
                          sendMessage(draftText);
                        }
                      }}
                      placeholder="Ask anything"
                      className="flex-1 bg-transparent outline-none text-lg"
                    />
                    <button
                      onClick={() => sendMessage(draftText)}
                      disabled={!draftText.trim()}
                      className="ml-3 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
                    >
                      <Send className="w-5 h-5" />
                    </button>
                  </div>
                </div>
              </div>
            ) : currentView === 'main' ? (
              <>
                <div ref={chatRef} className="flex-1 overflow-y-auto p-4 space-y-4" id="main-chat">
                  {messages
                    .filter(m => m.sessionId === currentSessionId && !m.threadId)
                    .map((message) => (
                      <div key={message.id}>
                        <MessageBubble 
                          message={message}
                          onTextSelection={handleTextSelection}
                          selectedText={selectedText}
                          selectionContext={selectionContext}
                          onCreateThread={openThread}
                          onCreateSelectedThread={(text) => {
                            openThread(message.id, text, null);
                            setSelectedText('');
                            setSelectionContext(null);
                          }}
                          siblingThreads={getSiblingThreads(message.id)}
                          suggestedThreads={suggestedThreads[message.id] || []}
                          onCreateSuggestedThread={createSuggestedThread}
                          threadDropdown={threadDropdowns[message.id]}
                          onToggleDropdown={() => toggleThreadDropdown(message.id)}
                          onNavigateToThread={navigateToThread}
                        />
                        {/* Thread summary under each message */}
                        {threads.filter(t => t.parentMsgId === message.id && !t.parentThreadId).length > 0 && (
                          <div className="mt-2 ml-8 flex flex-wrap gap-2">
                            {threads.filter(t => t.parentMsgId === message.id && !t.parentThreadId).map((thread, idx) => (
                              <div key={thread.id} className="flex items-center gap-2">
                                <button
                                  onClick={() => navigateToThread(thread.id)}
                                  className="flex items-center px-3 py-1 bg-blue-100 hover:bg-blue-200 rounded-lg text-blue-800 text-xs font-medium border border-blue-200 transition-colors"
                                  title={thread.contextText ? thread.contextText : `Thread #${thread.id.slice(-4)}`}
                                >
                                  <GitBranch className="w-3 h-3 mr-1" />
                                  <span>Thread {idx + 1}</span>
                                  <span className="ml-2 bg-blue-200 text-blue-900 rounded px-2 py-0.5">{getThreadMessages(thread.id).length} msg</span>
                                  {thread.contextText && (
                                    <span className="ml-2 italic text-gray-500 max-w-xs truncate">"{thread.contextText.slice(0, 30)}..."</span>
                                  )}
                                </button>
                                {/* Enroll Thread Outcome button with dropdown */}
                                <div className="relative">
                                  <button
                                    onClick={() => setThreadEnrollDropdown(thread.id)}
                                    className="px-2 py-1 bg-yellow-400 text-white text-xs rounded hover:bg-yellow-500"
                                  >
                                    <Download className="w-3 h-3 inline mr-1" /> Enroll
                                  </button>
                                  {threadEnrollDropdown === thread.id && (
                                    <div className="absolute z-10 mt-1 bg-white border rounded shadow-lg p-2">
                                      <div className="mb-2 text-xs font-medium">Choose Model</div>
                                      <select
                                        onChange={e => {
                                          const modelId = e.target.value;
                                          setThreadEnrollDropdown(null);
                                          // Generate summary
                                          const threadMsgs = getThreadMessages(thread.id).map(m => `${m.sender === 'user' ? 'User' : 'AI'}: ${m.content}`).join('\n');
                                          const summaryPrompt = `Summarize and enroll this thread into the main chat:\n${threadMsgs.slice(0, 1000)}`;
                                          // Generate AI response
                                          const modelObj = availableModels.find(m => m.id === modelId);
                                          let aiContent = '';
                                          if (modelObj?.type === 'visual') {
                                            aiContent = `🖼️ [Image generated by ${modelObj.name} for: "${summaryPrompt.slice(0, 50)}"]`;
                                          } else if (modelObj?.type === 'audio') {
                                            aiContent = `🔊 [Audio generated by ${modelObj.name} for: "${summaryPrompt.slice(0, 50)}"]`;
                                          } else if (modelObj?.type === 'video') {
                                            aiContent = `🎬 [Video generated by ${modelObj.name} for: "${summaryPrompt.slice(0, 50)}"]`;
                                          } else if (modelObj?.type === 'app' || modelObj?.type === 'code') {
                                            aiContent = `⚙️ [App/code generated by ${modelObj.name} for: "${summaryPrompt.slice(0, 50)}"]`;
                                          } else {
                                            aiContent = `AI: Would you like to enroll this thread outcome into the main discussion?\n${summaryPrompt}`;
                                          }
                                          setMessages(prev => [
                                            ...prev,
                                            {
                                              id: generateId(),
                                              sessionId: currentSessionId,
                                              content: aiContent,
                                              sender: 'AI',
                                              model: modelId,
                                              modelType: modelObj?.type || 'text',
                                              threadId: null, // main chat
                                              timestamp: new Date(),
                                            }
                                          ]);
                                        }}
                                        className="w-full border border-gray-300 rounded p-1 text-xs"
                                        defaultValue=""
                                      >
                                        <option value="" disabled>Choose a model...</option>
                                        {availableModels.map(model => (
                                          <option key={model.id} value={model.id}>{model.name} ({model.type})</option>
                                        ))}
                                      </select>
                                    </div>
                                  )}
                                </div>
                              </div>
                            ))}
                          </div>
                        )}
                        {/* Thread Display with Enhanced Hierarchy */}
                        <ThreadHierarchy 
                          parentMsgId={message.id}
                          threads={threads}
                          messages={messages}
                          compactMode={compactMode}
                          onNavigateToThread={navigateToThread}
                          onOpenThread={openThread}
                          onToggleThread={toggleThread}
                          onResolveThread={resolveThread}
                          onInviteToThread={(threadId) => {
                            setCurrentInviteThread(threadId);
                            setInviteModal(true);
                          }}
                          getThreadMessages={getThreadMessages}
                          getSiblingThreads={getSiblingThreads}
                          getChildThreads={getChildThreads}
                        />
                      </div>
                    ))}

                  {isTyping && (
                    <div className="flex justify-start">
                      <div className="bg-white border border-gray-200 px-4 py-3 rounded-2xl shadow-sm">
                        <div className="flex space-x-2">
                          <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                          <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0.1s'}}></div>
                          <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></div>
                        </div>
                      </div>
                    </div>
                  )}
                </div>

                {/* Enhanced Main Input */}
                <footer className="bg-white border-t border-gray-200 p-4">
                  <div className="flex items-center space-x-3 mb-3">
                    <select
                      value={inputModel}
                      onChange={e => setInputModel(e.target.value)}
                      className="px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                    >
                      {availableModels.map(model => (
                        <option key={model.id} value={model.id}>{model.name} ({model.type})</option>
                      ))}
                    </select>

                    <div className="flex-1 relative">
                      <input
                        type="text"
                        value={draftText}
                        onChange={(e) => setDraftText(e.target.value)}
                        onKeyPress={(e) => {
                          if (e.key === 'Enter' && draftText.trim()) {
                            sendMessage(draftText);
                          }
                        }}
                        placeholder="Message FlowChat..."
                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 pr-12"
                      />
                      <button
                        onClick={() => sendMessage(draftText)}
                        disabled={!draftText.trim()}
                        className="absolute right-2 top-1/2 transform -translate-y-1/2 p-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                      >
                        <Send className="w-4 h-4" />
                      </button>
                    </div>

                    <button
                      onClick={exportSession}
                      className="p-2 text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                      title="Export Session"
                    >
                      <Download className="w-5 h-5" />
                    </button>
                  </div>

                  <div className="flex items-center justify-between text-xs text-gray-500">
                    <div className="flex items-center space-x-4">
                      <span>{messages.filter(m => !m.threadId).length} messages</span>
                      <span>{activeThreads.length} threads</span>
                      <span className="flex items-center space-x-1">
                        <TreePine className="w-3 h-3" />
                        <span>Advanced Threading</span>
                      </span>
                    </div>
                    <div className="flex items-center space-x-2">
                      <Zap className="w-3 h-3" />
                      <span>FlowChat Next-Gen</span>
                    </div>
                  </div>
                </footer>
              </>
            ) : (
              <ThreadView
                threadId={currentView}
                threads={threads}
                messages={messages}
                availableModels={availableModels}
                suggestedQuestions={suggestedQuestions}
                isTyping={isTyping}
                onSwitchModel={switchModel}
                onOpenSubThread={openThread}
                onInviteToThread={(threadId) => {
                  setCurrentInviteThread(threadId);
                  setInviteModal(true);
                }}
                getRelatedThreads={getRelatedThreads}
                getThreadMessages={getThreadMessages}
                canInvite={canInvite}
                selectedText={selectedText}
                setSelectedText={setSelectedText}
                selectionContext={selectionContext}
                setSelectionContext={setSelectionContext}
                handleTextSelection={handleTextSelection}
                activeUsers={activeUsers}
                openThread={openThread}
              />
            )}
          </main>
        </div>
      </div>
    );
  };

  export default FlowChat;
